// 运行时修改地形高度（示意）
using UnityEngine;

public class TerrainRaise : MonoBehaviour
{
    [SerializeField] private Terrain terrain;
    private void Start()
    {
        var data = terrain.terrainData;
        float[,] heights = data.GetHeights(0, 0, 10, 10);
        for (int y = 0; y < 10; y++) for (int x = 0; x < 10; x++) heights[y, x] = 0.1f;
        data.SetHeights(0, 0, heights);
    }
}
